+#[test]
+fn a_running_feed_lowered_below_the_material_row_is_the_rating() {
+    let dir = temp_dir("running");
+    let mut c = setup(&dir);
+    let dr = catalog().into_iter().find(|(n, _)| *n == "DR-0600").map(|(_, t)| t).expect("catalog drill");
